import{_ as o,o as a,c as n,a2 as t}from"./chunks/framework.Buc7gXeZ.js";const u=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"dynamic-record-view/architecture.md","filePath":"dynamic-record-view/architecture.md"}'),i={name:"dynamic-record-view/architecture.md"};function r(c,e,d,s,l,p){return a(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><h2 id="layers" tabindex="-1">Layers <a class="header-anchor" href="#layers" aria-label="Permalink to &quot;Layers&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Core (framework-agnostic)          App\\Support\\DynamicRecordView\\Core\\*</span></span>
<span class="line"><span>  DynamicRecordView, RecordSection, RecordTab, Content\\*, Fields\\*,</span></span>
<span class="line"><span>  SubApplication, RelationshipActions, RelationPicker</span></span>
<span class="line"><span>  RecordViewRegistry (trusted key -&gt; class lookup)</span></span>
<span class="line"><span>        |</span></span>
<span class="line"><span>Resolution                         App\\Support\\DynamicRecordView\\Resolution\\{RecordResolver,EmbeddedTableContext,RelationshipMutator}</span></span>
<span class="line"><span>        |</span></span>
<span class="line"><span>Livewire adapters                  App\\Livewire\\DynamicRecordView\\{RecordView,OtherData}</span></span>
<span class="line"><span>        |</span></span>
<span class="line"><span>Blade                              resources/views/{components,livewire}/dynamic-record-view/*</span></span></code></pre></div><h2 id="recordviewregistry" tabindex="-1">RecordViewRegistry <a class="header-anchor" href="#recordviewregistry" aria-label="Permalink to &quot;RecordViewRegistry&quot;">​</a></h2><p>Livewire components must never carry a raw <code>DynamicRecordView</code> class name as public state — a malicious client could otherwise instantiate an arbitrary class. Instead, <code>RecordView</code> and <code>OtherData</code> carry a <code>#[Locked] string $recordViewKey</code>, resolved to the concrete class only through <code>App\\Support\\DynamicRecordView\\Core\\RecordViewRegistry::resolve()</code>, a server-side trusted key -&gt; class map. Modules register their views from their own <code>ServiceProvider::boot()</code> (see <code>Modules\\General\\Providers\\GeneralServiceProvider</code>), bound as a singleton. An unknown key throws <code>Exceptions\\UnknownRecordViewKeyException</code> before anything is instantiated.</p><p>Core has zero knowledge of Livewire, Blade, or <code>Modules\\*</code> — enforced by <code>tests/Feature/DynamicRecordView/ArchitectureTest.php</code>. A <code>DynamicRecordView</code> subclass can be unit tested with plain PHP objects, no HTTP, no Livewire test harness (see <code>tests/Unit/DynamicRecordView/CoreTest.php</code>).</p><h2 id="primary-section-vs-other-data-section" tabindex="-1">Primary section vs. Other Data section <a class="header-anchor" href="#primary-section-vs-other-data-section" aria-label="Permalink to &quot;Primary section vs. Other Data section&quot;">​</a></h2><p><code>DynamicRecordView::primarySection()</code> builds a <code>RecordSection</code> from <code>tabs()</code>. <code>DynamicRecordView::otherDataSection()</code> builds a second, independent <code>RecordSection</code> from <code>subApplications()</code> — one <code>RecordTab</code> per <code>SubApplication</code>, each holding a <code>TableContent</code> for that application&#39;s table.</p><p>These two sections are rendered by <strong>two separate Livewire components</strong>: <code>App\\Livewire\\DynamicRecordView\\RecordView</code> (primary) and <code>App\\Livewire\\DynamicRecordView\\OtherData</code> (other data), the latter mounted as a nested Livewire component keyed by the record id. Because they are genuinely separate component instances:</p><ul><li>switching the primary tab never touches <code>OtherData</code>&#39;s state or triggers a request for it, and vice versa (Milestone 4);</li><li>an inactive tab&#39;s content is never rendered, so an inactive <code>TableContent</code> never queries (see <code>other-data.blade.php</code>&#39;s <code>@if ($currentTab)</code> guard);</li><li>keying <code>OtherData</code> by <code>&#39;other-data-&#39;.$viewKey.&#39;-&#39;.$record-&gt;getKey()</code> means navigating to a different record (different key) tears down and remounts it fresh, while re-rendering the <em>same</em> record preserves its state.</li></ul><h2 id="embedding-dynamic-tables" tabindex="-1">Embedding Dynamic Tables <a class="header-anchor" href="#embedding-dynamic-tables" aria-label="Permalink to &quot;Embedding Dynamic Tables&quot;">​</a></h2><p>See <a href="./embedded-tables">embedded-tables.md</a> for the full mechanism. In short: <code>App\\Livewire\\DynamicTable\\Table::query()</code> is always the sole source of a table&#39;s own authorized base query, and <code>TableQueryBuilder::query()</code> only ever adds <code>where()</code>/<code>whereHas()</code> on top of it — it never resets or replaces the base builder. <code>Table::resolvedQuery()</code> layers one more constraint on top of that chain — the parent relation, resolved generically by <code>App\\Support\\DynamicRecordView\\Resolution\\EmbeddedTableContext</code> from bounded scalar <code>#[Locked]</code> props (<code>embedRecordViewKey</code>/<code>embedRecordId</code>/<code>embedSection</code>/ <code>embedTab</code>/<code>embedContent</code>), never from a bespoke per-relation subclass. The same <code>Table</code> subclass works standalone (unconstrained) and embedded any number of times for different parents (constrained) — this is enforced architecture, not convention.</p><p><code>Table</code> also splits table identity into a permanent <strong>storage key</strong> (<code>storageKey()</code>, used for preferences/saved views, shared across standalone and every embedded use) and a temporary <strong>instance key</strong> (<code>instanceIdentifier()</code>, used only for query-string namespacing and the Livewire component key, unique per embedding). See <a href="./embedded-tables#table-identity-storage-key-vs-instance-key">embedded-tables.md</a>.</p><h2 id="content-rendering" tabindex="-1">Content rendering <a class="header-anchor" href="#content-rendering" aria-label="Permalink to &quot;Content rendering&quot;">​</a></h2><p><code>resources/views/components/dynamic-record-view/content.blade.php</code> is the single shared renderer for every <code>Content</code> subclass in every tab — primary <em>and</em> Other Data alike. It replaces what were previously two separate, diverging <code>instanceof</code> branch sets in <code>record-view.blade.php</code> and <code>other-data.blade.php</code>. It enforces: <code>$content-&gt;isVisible($record)</code>, a stable <code>wire:key</code> per content block, and (for <code>TableContent</code>) passes only the bounded embed-context scalars described above — never the record itself — to the embedded <code>Table</code> component.</p><h2 id="link-unlink-mutation-engine" tabindex="-1">Link/Unlink mutation engine <a class="header-anchor" href="#link-unlink-mutation-engine" aria-label="Permalink to &quot;Link/Unlink mutation engine&quot;">​</a></h2><p><code>App\\Support\\DynamicRecordView\\Core\\RelationshipActions</code> and <code>RelationPicker</code> are real and wired: <code>TableContent::relationshipActions()</code> / <code>SubApplication::relationshipActions()</code> enable Link/Unlink UI and authorization for one embedded relation, executed server-side by <code>App\\Support\\DynamicRecordView\\Resolution\\RelationshipMutator</code>. See <a href="./relationship-actions">relationship-actions.md</a> and <a href="./relation-picker">relation-picker.md</a> for the full mechanism.</p><h2 id="country-cities-canonical-example" tabindex="-1">Country/Cities canonical example <a class="header-anchor" href="#country-cities-canonical-example" aria-label="Permalink to &quot;Country/Cities canonical example&quot;">​</a></h2><p><code>Modules\\General\\System\\World\\CountryRecordView</code> and <code>Modules\\General\\Livewire\\World\\Countries\\CitiesTable</code> are implemented and tested (see <code>tests/Feature/DynamicRecordView/CountryRecordViewTest.php</code>), reachable at <code>route(&#39;general.world.countries.show&#39;, [&#39;recordId&#39; =&gt; $country-&gt;id])</code>. <code>nnjeim/world</code>&#39;s <code>cities</code> table has a NOT NULL <code>country_id</code> foreign key (see <code>vendor/nnjeim/world/src/Database/Migrations/2020_07_07_055725_create_cities_table.php</code>), so — like <code>SubModule -&gt; Applications</code> — it is Link-only via <code>allowReassignment()</code>; ordinary Unlink is architecturally rejected. See <a href="./relationship-actions">relationship-actions.md</a>.</p><h2 id="genuinely-unimplemented" tabindex="-1">Genuinely unimplemented <a class="header-anchor" href="#genuinely-unimplemented" aria-label="Permalink to &quot;Genuinely unimplemented&quot;">​</a></h2><ul><li>Multi-select in the Relation Picker (single-select only) — see <a href="./relation-picker">relation-picker.md</a>.</li><li><code>RelationshipActions::reassignPolicy()</code> — a documented throwing stub, no audit/policy object behind it.</li><li><code>BelongsToMany</code> Link/Unlink — the code path exists in <code>RelationshipMutator</code> but nothing in this codebase has a real <code>BelongsToMany</code> relation to exercise it against.</li></ul>`,21)])])}const m=o(i,[["render",r]]);export{u as __pageData,m as default};
